import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"支援的檔案管理器與對話方塊整合","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/file-manager-support.md","filePath":"zh-HK/user-guide/file-manager-support.md","lastUpdated":1787586465000}'),n={name:"zh-HK/user-guide/file-manager-support.md"};function d(s,t,i,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="支援的檔案管理器與對話方塊整合" tabindex="-1">支援的檔案管理器與對話方塊整合 <a class="header-anchor" href="#支援的檔案管理器與對話方塊整合" aria-label="Permalink to &quot;支援的檔案管理器與對話方塊整合&quot;">​</a></h1><p>Lertaro 不僅是一款獨立的桌面啟動器，更具備深度嵌入各類檔案總管與軟體對話方塊的強大整合能力。透過無縫接管檔案互動，極大提升檔案開啟、儲存與目錄跳轉的效率。</p><h2 id="_1-三大核心整合能力" tabindex="-1">1. 三大核心整合能力 <a class="header-anchor" href="#_1-三大核心整合能力" aria-label="Permalink to &quot;1. 三大核心整合能力&quot;">​</a></h2><p>根據目標宿主視窗的特性，Lertaro 的整合最多可提供以下三種核心能力：</p><ul><li><strong>內嵌搜尋（Inline Search）</strong>：Lertaro 的極速搜尋框直接嵌入到目標視窗頂部或對話方塊內部，無需離開當前工作介面即可在當前目錄或全域發起檢索。</li><li><strong>快速導覽（Quick Navigation）</strong>：在目標視窗空白處按一下滑鼠中鍵（或按兩下左鍵），或按一下內嵌搜尋框的圖示，即可快顯包含當前已開啟資料夾、我的最愛、最近記錄與自訂快捷目錄的級聯選單。</li><li><strong>活動路徑偵測（Active Path Detection）</strong>：即時感知宿主視窗當前所處的實體檔案目錄，自動將搜尋範圍智慧限定在當前目錄內，或用於解析相對路徑操作。</li></ul><h2 id="_2-系統原生元件支援-內建開箱即用" tabindex="-1">2. 系統原生元件支援（內建開箱即用） <a class="header-anchor" href="#_2-系統原生元件支援-內建開箱即用" aria-label="Permalink to &quot;2. 系統原生元件支援（內建開箱即用）&quot;">​</a></h2><p>以下系統原生元件均由 Lertaro 核心引擎直接支援，無需單獨安裝或設定任何外掛模組：</p><table tabindex="0"><thead><tr><th style="text-align:left;">宿主視窗類型</th><th style="text-align:left;">內嵌搜尋</th><th style="text-align:left;">快速導覽觸發方式</th><th style="text-align:left;">活動路徑偵測</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 檔案總管</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">空白區域按兩下左鍵或按一下滑鼠中鍵</td><td style="text-align:left;">支援</td></tr><tr><td style="text-align:left;"><strong>現代開啟/儲存檔案對話方塊</strong></td><td style="text-align:left;">支援（直接嵌入對話方塊）</td><td style="text-align:left;">滑鼠中鍵，或按一下左鍵內嵌搜尋框 Logo 圖示</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>傳統開啟/儲存檔案對話方塊</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下左鍵內嵌搜尋框 Logo 圖示</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>傳統「瀏覽資料夾」對話方塊</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下左鍵內嵌搜尋框 Logo 圖示</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>在各類檔案選取對話方塊中，由於 Lertaro 已經直接內嵌在對話方塊內部，因此無需額外的活動路徑偵測；按一下快速導覽中的目標後，對話方塊會直接精準跳轉到該目錄。</p></div><h2 id="_3-專業第三方檔案管理器支援-可選外掛模組" tabindex="-1">3. 專業第三方檔案管理器支援（可選外掛模組） <a class="header-anchor" href="#_3-專業第三方檔案管理器支援-可選外掛模組" aria-label="Permalink to &quot;3. 專業第三方檔案管理器支援（可選外掛模組）&quot;">​</a></h2><p>針對進階用戶常用的第三方檔案管理工具，Lertaro 提供了深度對接外掛模組。你可以在<a href="./settings/plugins.html"><strong>設定 → 外掛模組</strong></a>中按需啟用，並在此外掛模組的<strong>設定</strong>面板中單獨開關內嵌搜尋與快速導覽：</p><table tabindex="0"><thead><tr><th style="text-align:left;">檔案管理器</th><th style="text-align:left;">內嵌搜尋</th><th style="text-align:left;">快速導覽觸發方式</th><th style="text-align:left;">活動路徑偵測</th><th style="text-align:left;">核心通訊技術與協定</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">檔案列表區域按一下滑鼠中鍵</td><td style="text-align:left;">支援</td><td style="text-align:left;"><code>WM_COPYDATA</code> 官方遠端控制介面</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">檔案列表區域按一下滑鼠中鍵</td><td style="text-align:left;">支援</td><td style="text-align:left;"><code>WM_COPYDATA</code> 官方訊息介面</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">檔案列表區域按一下滑鼠中鍵</td><td style="text-align:left;">支援</td><td style="text-align:left;">專用程序介面通訊</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">檔案列表區域按一下滑鼠中鍵</td><td style="text-align:left;">支援</td><td style="text-align:left;">Windows UI Automation 現代化自動化介面</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">支援</td><td style="text-align:left;">檔案列表區域按一下滑鼠中鍵</td><td style="text-align:left;">支援</td><td style="text-align:left;">Windows UI Automation 現代化自動化介面</td></tr></tbody></table><h3 id="directory-opus-專屬深度整合" tabindex="-1">Directory Opus 專屬深度整合 <a class="header-anchor" href="#directory-opus-專屬深度整合" aria-label="Permalink to &quot;Directory Opus 專屬深度整合&quot;">​</a></h3><ul><li><strong>遞迴資料夾大小欄（Lertaro 大小）</strong>：啟用 Directory Opus 外掛模組中的「啟用 Lertaro 大小欄」後，Lertaro 會自動向 Directory Opus 注入自訂腳本欄。該欄直接從 Lertaro 的記憶體索引讀取資料夾遞迴總容量，<strong>完全無需掃描磁碟</strong>即可秒級呈現整個磁碟所有資料夾的實際體積。</li><li><strong>持久化設定</strong>：在 Directory Opus 的欄選擇器中新增「Lertaro 大小」欄後，依次按一下<strong>資料夾 → 資料夾格式 → 儲存 → 將格式儲存給所有資料夾</strong>即可全域生效。</li></ul><h3 id="everything-相容服務-ipc" tabindex="-1">Everything 相容服務 (IPC) <a class="header-anchor" href="#everything-相容服務-ipc" aria-label="Permalink to &quot;Everything 相容服務 (IPC)&quot;">​</a></h3><p>在<a href="./settings/general.html#系統"><strong>設定 → 一般 → 系統</strong></a>中勾選**啟用 Everything 相容服務 (IPC)**後，Lertaro 會在後台模擬標準的 Everything Win32 IPC 介面。Directory Opus、Total Commander、Flow Launcher 等第三方軟體無需額外安裝或運行 Everything，即可直接透過原有的 Everything 外掛模組調用 Lertaro 的極速記憶體索引。</p><h2 id="_4-常用軟體自繪對話方塊支援-專用外掛模組" tabindex="-1">4. 常用軟體自繪對話方塊支援（專用外掛模組） <a class="header-anchor" href="#_4-常用軟體自繪對話方塊支援-專用外掛模組" aria-label="Permalink to &quot;4. 常用軟體自繪對話方塊支援（專用外掛模組）&quot;">​</a></h2><p>許多專業軟體並未使用 Windows 原生對話方塊，而是自繪了特殊視窗。Lertaro 為以下主流軟體的專用對話方塊提供了客製化內嵌支援：</p><table tabindex="0"><thead><tr><th style="text-align:left;">軟體名稱與對話方塊類型</th><th style="text-align:left;">內嵌搜尋</th><th style="text-align:left;">快速導覽觸發方式</th><th style="text-align:left;">配接說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 開啟/儲存對話方塊</td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下內嵌 Logo 圖示</td><td style="text-align:left;">全面覆蓋 WPS 文字、試算表、簡報與 PDF 元件</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 解壓縮對話方塊</td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下內嵌 Logo 圖示</td><td style="text-align:left;">解壓縮檔案時快速定位目標解壓縮目錄</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 解壓縮對話方塊</td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下內嵌 Logo 圖示</td><td style="text-align:left;">快速指定解壓縮輸出路徑</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 新增檔案對話方塊</td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下內嵌 Logo 圖示</td><td style="text-align:left;">壓縮封裝時快速選擇來源檔案</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 開啟/儲存對話方塊</td><td style="text-align:left;">支援</td><td style="text-align:left;">滑鼠中鍵，或按一下內嵌 Logo 圖示</td><td style="text-align:left;">適配工程圖紙的快速歸檔與調用</td></tr></tbody></table><p>此外掛模組透過識別視窗底層的控制項結構與控制代碼層級進行掛載，不受軟體多語言介面或不同版本介面微調的影響。</p>',20)])])}const x=e(n,[["render",d]]);export{h as __pageData,x as default};
